from rdkit import Chem
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
m=Chem.MolFromMolFile('organic.mol',removeHs=False);p=np.load('coords.npy')
fig=plt.figure(figsize=(14,8));
for ii,vs in enumerate([(90,-90),(20,-75)]):
 ax=fig.add_subplot(1,2,ii+1,projection='3d')
 for b in m.GetBonds():
  a,c=b.GetBeginAtomIdx(),b.GetEndAtomIdx()
  if m.GetAtomWithIdx(a).GetSymbol()=='H' or m.GetAtomWithIdx(c).GetSymbol()=='H':continue
  ax.plot(*p[[a,c]].T,color='gray',lw=1.2)
 for j,ds in enumerate([[0,64,128,141],[29,93,154,167]]):
  for d in ds:ax.plot(*p[[180+j,d]].T,color='cyan')
 colors={'C':'#333333','O':'red','F':'limegreen','Cr':'cyan'}
 for i in range(len(p)):
  el=m.GetAtomWithIdx(i).GetSymbol() if i<180 else 'Cr'
  if el=='H':continue
  ax.scatter(*p[i],color=colors[el],s=50 if el=='Cr' else 12)
  if i<42:ax.text(*p[i],str(i),fontsize=6)
 ax.view_init(*vs);ax.set_box_aspect([1,1,1]);ax.set_xlim(-8,8);ax.set_ylim(-8,8);ax.set_zlim(-8,8)
plt.savefig('render.png',dpi=150)
